div.script:
document.addEventListener("DOMContentLoaded", function () {
    var container = document.getElementById("order_lines_container");
    var btnAdd = document.getElementById("btn_add_line");
    var btnDetails = document.getElementById("btn_show_details");
    var form = document.getElementById("cafe_order_form");
    var totalDisplay = document.getElementById("display_total_price");
    var dummyDatalist = document.getElementById("dummy_product_datalist");

    var productsList = [];
    if (dummyDatalist) {
        var options = dummyDatalist.querySelectorAll("option");
        options.forEach(function(opt) {
            productsList.push({
                id: parseInt(opt.getAttribute("data-id")),
                name: opt.value,
                price: parseFloat(opt.getAttribute("data-price")) || 0,
                barcode: opt.getAttribute("data-barcode") || ""
            });
        });
    }

    function formatRupiah(number) {
        return "Rp. " + Number(number).toLocaleString("id-ID");
    }

    function addOrderLine() {
        var rowId = "line_" + Date.now() + "_" + Math.floor(Math.random() * 1000);
        var box = document.createElement("div");
        box.className = "order-line-box";
        box.id = rowId;

        box.innerHTML = `
            <div style="margin-bottom: 12px; display: flex; gap: 12px; align-items: flex-end;">
                <div style="flex: 1;">
                    <label style="font-size:12px; font-weight:700; margin-bottom:4px; display:block;">Nama Produk <span class="required-asterisk">*</span></label>
                    <input type="text" class="custom-input product-input" list="dummy_product_datalist" placeholder="Ketik nama / barcode produk..." required/>
                    <input type="hidden" class="product-id-input"/>
                </div>
                <div style="flex: 0 0 auto;">
                    <button type="button" class="btn-delete-line" title="Hapus">&times;</button>
                </div>
            </div>
            <div class="order-line-row">
                <div class="col-price" style="flex: 2;">
                    <label style="font-size:12px; font-weight:700; margin-bottom:4px; display:block;">Harga Jual</label>
                    <input type="text" class="custom-input price-input" value="Rp. 0" readonly style="background-color: #e9ecef;"/>
                </div>
                <div class="col-qty" style="flex: 1;">
                    <label style="font-size:12px; font-weight:700; margin-bottom:4px; display:block;">Qty</label>
                    <input type="number" class="custom-input qty-input" value="1" min="1" step="1" required/>
                </div>
            </div>
        `;

        container.appendChild(box);

        var productInput = box.querySelector(".product-input");
        var productIdInput = box.querySelector(".product-id-input");
        var priceEl = box.querySelector(".price-input");
        var qtyEl = box.querySelector(".qty-input");
        var btnDelete = box.querySelector(".btn-delete-line");

        function updateSelectedProduct(allowPartial) {
            var val = productInput.value.trim().toLowerCase();
            var found = null;

            if (val) {
                // First try exact match by name or barcode
                for (var i = 0; i < productsList.length; i++) {
                    var p = productsList[i];
                    if (p.name.toLowerCase() === val || (p.barcode && p.barcode.toLowerCase() === val)) {
                        found = p;
                        break;
                    }
                }
                // If allowPartial is true (e.g. on blur/change event), try partial matching
                if (!found && allowPartial) {
                    for (var j = 0; j < productsList.length; j++) {
                        var prod = productsList[j];
                        if (prod.name.toLowerCase().includes(val) || (prod.barcode && prod.barcode.toLowerCase().includes(val))) {
                            found = prod;
                            break;
                        }
                    }
                }
            }

            if (found) {
                productIdInput.value = found.id;
                priceEl.value = formatRupiah(found.price);
                priceEl.setAttribute("data-price", found.price);
                if (allowPartial) {
                    productInput.value = found.name;
                }
            } else {
                productIdInput.value = "";
                priceEl.value = "Rp. 0";
                priceEl.removeAttribute("data-price");
            }
            calculateTotal();
        }

        productInput.addEventListener("change", function() {
            updateSelectedProduct(true);
        });

        productInput.addEventListener("input", function() {
            updateSelectedProduct(false);
        });

        qtyEl.addEventListener("input", function () {
            calculateTotal();
        });

        btnDelete.addEventListener("click", function () {
            if (container.querySelectorAll(".order-line-box").length > 1) {
                box.remove();
                calculateTotal();
            } else {
                alert("Minimal 1 menu pesanan harus ada.");
            }
        });

        calculateTotal();
    }

    function calculateTotal() {
        var total = 0;
        var boxes = container.querySelectorAll(".order-line-box");
        boxes.forEach(function (box) {
            var productIdInput = box.querySelector(".product-id-input");
            var priceEl = box.querySelector(".price-input");
            var qtyEl = box.querySelector(".qty-input");
            if (productIdInput.value) {
                var price = parseFloat(priceEl.getAttribute("data-price")) || 0;
                var qty = parseFloat(qtyEl.value) || 0;
                total += price * qty;
            }
        });
        totalDisplay.textContent = formatRupiah(total);
        return total;
    }

    btnAdd.addEventListener("click", function () {
        addOrderLine();
    });

    btnDetails.addEventListener("click", function () {
        var custNameInput = document.getElementById("customer_name").value.trim();
        var tableNumInput = document.getElementById("table_number").value.trim();

        document.getElementById("modal_cust_name").textContent = custNameInput ? custNameInput : "-";
        document.getElementById("modal_table_num").textContent = tableNumInput ? tableNumInput : "-";

        var boxes = container.querySelectorAll(".order-line-box");
        var menuItems = [];
        var totalQty = 0;
        var grandTotal = 0;

        boxes.forEach(function (box) {
            var productInput = box.querySelector(".product-input");
            var productIdInput = box.querySelector(".product-id-input");
            var priceEl = box.querySelector(".price-input");
            var qtyEl = box.querySelector(".qty-input");
            if (productIdInput.value) {
                var pName = productInput.value;
                var price = parseFloat(priceEl.getAttribute("data-price")) || 0;
                var qty = parseFloat(qtyEl.value) || 0;
                var subtotal = price * qty;

                menuItems.push({
                    name: pName,
                    price: price,
                    qty: qty,
                    subtotal: subtotal
                });

                totalQty += qty;
                grandTotal += subtotal;
            }
        });

        var menuContainer = document.getElementById("modal_menu_container");
        if (menuItems.length === 0) {
            menuContainer.innerHTML = '<div class="menu-empty-box">Belum ada menu yang dipilih.</div>';
        } else {
            var html = '<table class="table table-bordered table-sm" style="font-size:14px;"><thead class="thead-light"><tr><th>Produk</th><th class="text-right">Harga</th><th class="text-center">Qty</th><th class="text-right">Subtotal</th></tr></thead><tbody>';
            menuItems.forEach(function (item) {
                html += '<tr><td>' + item.name + '</td><td class="text-right">' + formatRupiah(item.price) + '</td><td class="text-center">' + item.qty + '</td><td class="text-right">' + formatRupiah(item.subtotal) + '</td></tr>';
            });
            html += '</tbody></table>';
            menuContainer.innerHTML = html;
        }

        document.getElementById("modal_total_types").textContent = menuItems.length + " menu";
        document.getElementById("modal_total_qty").textContent = totalQty + " porsi";
        document.getElementById("modal_total_price").textContent = formatRupiah(grandTotal);

        if (window.$ && window.$.fn && window.$.fn.modal) {
            $('#modalOrderDetails').modal('show');
        } else {
            var modalEl = document.getElementById('modalOrderDetails');
            if (modalEl) {
                modalEl.classList.add('show');
                modalEl.style.display = 'block';
            }
        }
    });

    // Event listener to close modal if bootstrap modal not loaded
    document.querySelectorAll('[data-dismiss="modal"]').forEach(function (btn) {
        btn.addEventListener('click', function () {
            document.querySelectorAll('.modal').forEach(function(m) {
                if (window.$ && window.$.fn && window.$.fn.modal) {
                    $(m).modal('hide');
                }
                m.classList.remove('show');
                m.style.display = 'none';
            });
        });
    });

    function showConfirmModal() {
        if (window.$ && window.$.fn && window.$.fn.modal) {
            $('#modalConfirmOrder').modal('show');
        } else {
            var modalEl = document.getElementById('modalConfirmOrder');
            if (modalEl) {
                modalEl.classList.add('show');
                modalEl.style.display = 'block';
            }
        }
    }

    function hideConfirmModal() {
        if (window.$ && window.$.fn && window.$.fn.modal) {
            $('#modalConfirmOrder').modal('hide');
        } else {
            var modalEl = document.getElementById('modalConfirmOrder');
            if (modalEl) {
                modalEl.classList.remove('show');
                modalEl.style.display = 'none';
            }
        }
    }

    var isConfirmed = false;

    form.addEventListener("submit", function (e) {
        if (isConfirmed) {
            return true;
        }

        e.preventDefault();

        if (!form.checkValidity()) {
            form.reportValidity();
            return false;
        }

        var lines = [];
        var boxes = container.querySelectorAll(".order-line-box");
        boxes.forEach(function (box) {
            var productIdInput = box.querySelector(".product-id-input");
            var priceEl = box.querySelector(".price-input");
            var qtyEl = box.querySelector(".qty-input");
            if (productIdInput.value) {
                var price = parseFloat(priceEl.getAttribute("data-price")) || 0;
                lines.push({
                    product_id: parseInt(productIdInput.value),
                    quantity: parseFloat(qtyEl.value) || 1,
                    price_unit: price
                });
            }
        });

        if (lines.length === 0) {
            alert("Silakan pilih minimal 1 produk menu.");
            return false;
        }

        document.getElementById("lines_data").value = JSON.stringify(lines);

        showConfirmModal();
        return false;
    });

    var btnModalAddMenu = document.getElementById("btn_modal_add_menu");
    if (btnModalAddMenu) {
        btnModalAddMenu.addEventListener("click", function() {
            hideConfirmModal();
            addOrderLine();
        });
    }

    var btnModalConfirmYes = document.getElementById("btn_modal_confirm_yes");
    if (btnModalConfirmYes) {
        btnModalConfirmYes.addEventListener("click", function() {
            hideConfirmModal();
            isConfirmed = true;
            form.submit();
        });
    }

    // Initial line
    addOrderLine();
});
